import { Lock, ShieldCheck } from 'lucide-react'
import { formatDate } from '../utils/progress'

/**
 * On-screen preview of the VerifyIT certificate (the official copy is the PDF generated by the server).
 * `locked` blurs the preview until the requirements are complete.
 */
export default function CertificatePreview({ recipientName, issuedAt, certificateNumber, locked = false, className = '' }) {
  return (
    <figure className={`relative ${className}`}>
      <div
        className={`keep-palette relative aspect-[1.414/1] w-full overflow-hidden rounded-md border-[3px] border-navy-900 bg-white p-[3%] shadow-sm ${
          locked ? 'select-none' : ''
        }`}
        aria-hidden={locked ? 'true' : undefined}
      >
        <div className="flex h-full flex-col items-center justify-between border border-cyan-600 px-[6%] py-[4%] text-center">
          <div>
            <p className="font-display text-[clamp(0.7rem,2.2vw,1.1rem)] font-extrabold text-navy-900">
              Verify<span className="text-cyan-600">IT</span>
            </p>
            <p className="mt-[2%] font-serif text-[clamp(0.8rem,3vw,1.6rem)] font-bold uppercase tracking-[0.12em] text-navy-900">
              Certificate of Completion
            </p>
            <span className="mx-auto mt-[2%] block h-px w-1/5 bg-cyan-600" />
          </div>
          <div className={locked ? 'blur-sm' : ''}>
            <p className="font-serif text-[clamp(0.55rem,1.5vw,0.85rem)] text-slate-600">This certifies that</p>
            <p className="mt-[2%] font-serif text-[clamp(0.85rem,3.2vw,1.75rem)] font-bold text-navy-900">
              {recipientName || 'Your Name'}
            </p>
            <p className="mt-[2%] font-serif text-[clamp(0.55rem,1.5vw,0.85rem)] text-slate-600">has successfully completed</p>
            <p className="mt-[1%] text-[clamp(0.5rem,1.6vw,0.9rem)] font-bold uppercase tracking-wide text-navy-900">
              Media Literacy and Online Misinformation Awareness
            </p>
          </div>
          <div className="flex w-full items-end justify-between text-left text-[clamp(0.45rem,1.2vw,0.7rem)] text-slate-500">
            <span>
              <span className="block font-semibold uppercase tracking-wider">Date of issue</span>
              <span className="text-navy-900">{issuedAt ? formatDate(issuedAt) : '—'}</span>
            </span>
            <span className="text-right">
              <span className="block font-semibold uppercase tracking-wider">Certificate no.</span>
              <span className="font-mono text-navy-900">{certificateNumber ?? 'VIT-····-····-····-····'}</span>
            </span>
          </div>
        </div>
        {locked && (
          <div className="absolute inset-0 grid place-items-center bg-white/40">
            <span className="flex items-center gap-2 rounded-full bg-navy-900 px-4 py-2 text-sm font-semibold text-white shadow">
              <Lock className="size-4" aria-hidden="true" />
              Locked
            </span>
          </div>
        )}
      </div>
      <figcaption className="mt-2 flex items-center gap-1.5 text-xs text-slate-500">
        <ShieldCheck className="size-3.5 text-cyan-600" aria-hidden="true" />
        {locked ? 'Preview. Complete every requirement to unlock your certificate.' : 'Preview. The official copy is the downloadable PDF.'}
      </figcaption>
    </figure>
  )
}
